/// Φ(α) for a phase angle in radians (clamped to 0..π), linear between the table's degrees.
/// Mirror of `dust_phase_function`.
pub fn phase_function(alpha_rad: f32) -> f32 {
  let deg = (alpha_rad * (180.0 / core::f32::consts::PI)).clamp(0.0, 180.0);
  let i = (deg as usize).min(179);
  let f = deg - i as f32;
  PHASE_HM_0DEG[i] + (PHASE_HM_0DEG[i + 1] - PHASE_HM_0DEG[i]) * f
}

/// The radiance weight of a packet, `p · Φ(α) / r_h²` (r_h in AU): its optical depth times this is
/// the radiance factor I/F the pixel shows (the composite's white point is then a radiance factor,
/// `white_to_mag_arcsec2`). `sun_dir` is the unit direction from the packet to the Sun and `to_eye`
/// the vector from the packet to the eye (any length; a zero length counts as α = 0), both in the
/// same axes. Mirror of `dust_radiance_weight`.
pub fn radiance_weight(albedo: f32, sun_dir: [f32; 3], to_eye: [f32; 3], r_h_au: f32) -> f32 {
  let n = to_eye[0] * to_eye[0] + to_eye[1] * to_eye[1] + to_eye[2] * to_eye[2];
  let cos_a = if n > 0.0 {
    (sun_dir[0] * to_eye[0] + sun_dir[1] * to_eye[1] + sun_dir[2] * to_eye[2])
      / aethervk_oshal_rlib::math::FloatLike::sqrt(n)
  } else {
    1.0
  };
  let alpha = aethervk_oshal_rlib::math::FloatLike::acos(cos_a.clamp(-1.0, 1.0));
  let r = r_h_au.max(1e-6);
  albedo * phase_function(alpha) / (r * r)
}
